package wtf.tatp.meowtils.mixin;
import com.mojang.blaze3d.platform.InputConstants; import net.minecraft.client.KeyMapping; import net.minecraft.client.Minecraft; import org.spongepowered.asm.mixin.Mixin; import org.spongepowered.asm.mixin.injection.At; import org.spongepowered.asm.mixin.injection.Inject; import org.spongepowered.asm.mixin.injection.callback.CallbackInfo; import wtf.tatp.meowtils.module.utility.HotbarLock; import wtf.tatp.meowtils.module.utility.NullMove;
@Mixin(KeyMapping.class) public abstract class KeyMappingMixin { @Inject(method="set",at=@At("HEAD"),cancellable=true) private static void filter(InputConstants.Key key,boolean pressed,CallbackInfo ci){if(NullMove.shouldOverride()&&NullMove.isMovementKey(key)){if(!NullMove.accept(key,pressed)){ci.cancel();return;}NullMove.update(key,pressed);}var c=Minecraft.getInstance();if(pressed&&key.equals(((KeyMappingAccessor)(Object)c.options.keyDrop).meowtils$getKey())&&HotbarLock.blocksDrop())ci.cancel();} }
